effect.shader:
precision highp float;
#define TAU 6.28318530718
#define MAX_ITER 12
float waterHighlight(vec2 p, float time, float foaminess, float detail) {
vec2 i = vec2(p);
float c = 0.0;
float foaminess_factor = mix(1.0, 6.0, foaminess);
float inten = .005 * foaminess_factor;
int iterations = int(clamp(detail, 1.0, float(MAX_ITER)));
for (int n = 0; n < MAX_ITER; n++) {
if (n >= iterations) break;
float f_n = float(n + 1);
float t = time * (0.0 - (3.5 / f_n));
i = p + vec2(cos(t - i.x) + sin(t + i.y), sin(t - i.y) + cos(t + i.x));
c += 1.0 / length(vec2(p.x / (sin(i.x + t)), p.y / (cos(i.y + t))));
}
c = 0.2 + c / (inten * float(iterations));
c = 1.17 - pow(abs(c), 1.4);
c = pow(abs(c), 8.0);
return c / sqrt(foaminess_factor);
}
void main() {
vec2 uv = acLayerNorm.xy;
float boundsMask = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
float aspect = acLayerSize.x / acLayerSize.y;
vec2 uv_square = vec2(uv.x * aspect, uv.y);
float dist_center = pow(1.0 * length(uv - 0.5), 0.5);
float foaminess = smoothstep(0.4, 8.0, dist_center);
float clearness = 0.9 + 0.5 * smoothstep(0.5, 0.1, dist_center);
float time = (acTime * 0.02) + (progress * 0.1) + 23.0;
vec2 stretchFactor = stretch / 500.0;
vec2 p_uv = (uv_square / max(stretchFactor, 0.01)) * TAU * frequency;
vec2 p = mod(p_uv, TAU) - 250.0;
float c = waterHighlight(p, time, foaminess, detail);
float eps = 0.05;
float c_x = waterHighlight(p + vec2(eps, 0.0), time, foaminess, detail);
float c_y = waterHighlight(p + vec2(0.0, eps), time, foaminess, detail);
vec2 displacement = vec2(c - c_x, c - c_y) * warp;
displacement.x /= aspect;
vec2 distortedUV = uv + displacement;
vec4 base = texture2DCv(inputImg.texture, distortedUV);
if (distortedUV.x > 1.0 || distortedUV.x < 0.0 || distortedUV.y > 1.0 || distortedUV.y < 0.0) {
base = vec4(0.0);
}
vec3 highlightColor = mix(bgColor.rgb, wavesColor.rgb, clamp(c, 0.0, 1.0));
highlightColor = mix(bgColor.rgb, highlightColor, clearness);
vec3 finalColor = mix(base.rgb, highlightColor * brightness, blend);
float finalAlpha = base.a * boundsMask;
gl_FragColor = vec4(finalColor, finalAlpha);
}
